WITH recent_products AS (SELECT * FROM products WHERE launch_date > '2024-11-14' OR YEAR(launch_date) = 2024), ProductsStats AS (SELECT CASE WHEN stock_qty >= 354 THEN 'high' WHEN stock_qty >= 142 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(DISTINCT price) AS unique_brands FROM recent_products GROUP BY CASE WHEN stock_qty >= 354 THEN 'high' WHEN stock_qty >= 142 THEN 'mid' ELSE 'low' END) SELECT * FROM ProductsStats ORDER BY stock_qty_bucket;
